#!/usr/bin/env node
// Writing standard check (MASTER_PROMPT section 13). Node built-ins only; the same file is copied into each repo.
//
// Scans user-facing text and fails on em dashes, en dashes used as punctuation, emoji and the banned phrases.
//   - web/src/**/*.{ts,tsx}: string literals, template text, JSX text and JSX attribute strings. Comments, code,
//     tests and generated files are not user-facing and are skipped.
//   - every *.md in the repo, minus code blocks, inline code and link targets.
// Skipped everywhere: dependencies (lib/, node_modules/), build output, raw run data under evidence/ and
// analysis/data/, and license files.
//
// A line can opt out with a comment holding `writing-check-ignore` (same line) or `writing-check-ignore-next-line`
// (line above). Every opt-out needs a reason next to it.
//
// Usage: node tools/check-writing.mjs [--root <dir>] [--json]

import { execFileSync } from "node:child_process";
import { readdirSync, readFileSync, statSync } from "node:fs";
import { join, relative, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";

const SKIP_DIRS = [
  /(^|\/)node_modules\//,
  /^(contracts\/)?lib\//,
  /^contracts\/(out|cache|broadcast)\//,
  /(^|\/)\.(git|next|venv)\//,
  /(^|\/)(coverage|dist|test-results|playwright-report)\//,
  /^evidence\//,
  /^analysis\/data\//,
  /(^|\/)src\/generated\//,
];
const LICENSE_FILE = /(^|\/)(LICEN[CS]E|COPYING|NOTICE)[^/]*$/i;
const TEST_FILE = /(\.(test|spec)\.tsx?$)|((^|\/)(__tests__|tests?)\/)/;
const GENERATED_HEADER = /@generated|auto-?generated|generated by|do not edit/i;

const DETERMINERS =
  "the|a|an|this|that|these|those|our|your|their|its|his|her|my|it|them|us|you|me|existing|every|each|all|any|some";

/** @type {{ id: string, re: RegExp, message: string }[]} */
const RULES = [
  { id: "em-dash", re: /—|&mdash;|&#8212;|&#x2014;|\\u2014/giu, message: "em dash" },
  {
    id: "en-dash",
    re: /(?:(?<=\s|^)(?:–|&ndash;)(?=\s|$))|(?:(?<=\p{L})(?:–|&ndash;)(?=\p{L}))/gmu,
    message: "en dash used as punctuation",
  },
  { id: "emoji", re: /[\p{Extended_Pictographic}\p{Regional_Indicator}]/gu, message: "emoji" },
  { id: "banned", re: /\brevolutionar(?:y|ies)\b/giu, message: "banned word: revolutionary" },
  { id: "banned", re: /\bseamless(?:ly)?\b/giu, message: "banned word: seamless" },
  { id: "banned", re: /\bunlock(?:s|ed|ing)?\b/giu, message: "banned word: unlock" },
  { id: "banned", re: /\bunleash(?:es|ed|ing)?\b/giu, message: "banned word: unleash" },
  { id: "banned", re: /\bsupercharg(?:e|es|ed|ing)\b/giu, message: "banned word: supercharge" },
  { id: "banned", re: /\bgame[- ]?chang(?:ing|er|ers)\b/giu, message: "banned word: game-changing" },
  { id: "banned", re: /\bcutting[- ]edge\b/giu, message: "banned word: cutting-edge" },
  { id: "banned", re: /\bnext[- ]gen(?:eration)?\b/giu, message: "banned word: next-generation" },
  { id: "banned", re: /\brobust(?:ly|ness)?\b/giu, message: "banned word: robust" },
  {
    id: "banned",
    re: new RegExp(`\\bleverag(?:e|es|ed|ing)\\s+(?:${DETERMINERS})\\b`, "giu"),
    message: "banned: leverage as a verb",
  },
  { id: "banned", re: /\bdelv(?:e|es|ed|ing)\b/giu, message: "banned word: delve" },
  { id: "banned", re: /\belevat(?:e|es|ed|ing)\b/giu, message: "banned word: elevate" },
  { id: "banned", re: /\bempower(?:s|ed|ing|ment)?\b/giu, message: "banned word: empower" },
  { id: "banned", re: /\bin today[’']s world\b/giu, message: "banned phrase: in today's world" },
  {
    id: "banned",
    re: /\bnot (?:just|only|merely|simply)\b[^.!?\n]{1,80}?\bbut\b/giu,
    message: 'banned construction: "not just X but Y"',
  },
];

// ---------------------------------------------------------------------------------------------------------------
// File discovery

function listFiles(root) {
  try {
    const out = execFileSync("git", ["ls-files", "-z", "--cached", "--others", "--exclude-standard"], {
      cwd: root,
      encoding: "utf8",
      maxBuffer: 256 * 1024 * 1024,
      stdio: ["ignore", "pipe", "ignore"],
    });
    return out.split("\0").filter((f) => f.length > 0);
  } catch {
    return walk(root, root);
  }
}

function walk(root, dir) {
  /** @type {string[]} */
  const files = [];
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = join(dir, entry.name);
    const rel = relative(root, full).split(sep).join("/");
    if (entry.isDirectory()) {
      if (!SKIP_DIRS.some((re) => re.test(`${rel}/`))) files.push(...walk(root, full));
    } else if (entry.isFile()) {
      files.push(rel);
    }
  }
  return files;
}

function selectFiles(files) {
  return files.filter((f) => {
    if (SKIP_DIRS.some((re) => re.test(f)) || LICENSE_FILE.test(f)) return false;
    if (f.endsWith(".md")) return true;
    return /^web\/src\/.*\.tsx?$/.test(f) && !TEST_FILE.test(f.slice("web/src/".length)) && !f.endsWith(".d.ts");
  });
}

// ---------------------------------------------------------------------------------------------------------------
// TypeScript / TSX text extraction. A small lexer, not a parser: it tracks strings, template literals, comments,
// regex literals and JSX nesting, which is all it needs to tell user-facing text from code.

const REGEX_PREV_WORDS = new Set([
  "return",
  "typeof",
  "case",
  "do",
  "else",
  "in",
  "of",
  "void",
  "yield",
  "await",
  "delete",
  "throw",
  "new",
]);
const JSX_PREV_WORDS = new Set(["return", "yield", "default", "await", "case"]);
const EXPR_START = "(,=:[!&|?{};+-*%<>~^";
const IDENT = /[\p{L}\p{N}_$]/u;

/**
 * @param {string} src
 * @param {boolean} tsx
 * @returns {{ text: string, offset: number }[]}
 */
export function extractTsText(src, tsx) {
  /** @type {{ text: string, offset: number }[]} */
  const out = [];
  /** @type {({ kind: "js", depth: number } | { kind: "template" } | { kind: "tag", closing: boolean, started: boolean } | { kind: "children" })[]} */
  const stack = [{ kind: "js", depth: 0 }];
  const n = src.length;
  let i = 0;
  let prev = "";
  let prevWord = "";

  const emit = (from, to) => {
    if (to > from) out.push({ text: src.slice(from, to), offset: from });
  };
  const readQuoted = (start, quote, escapes) => {
    let j = start + 1;
    while (j < n && src[j] !== quote) {
      if (escapes && src[j] === "\\") j += 2;
      else if (escapes && src[j] === "\n") break;
      else j++;
    }
    emit(start + 1, Math.min(j, n));
    return j + 1;
  };
  const afterValue = () => {
    prev = "a";
    prevWord = "";
  };

  while (i < n) {
    const top = stack[stack.length - 1];
    const c = src[i];

    if (top.kind === "js") {
      if (/\s/.test(c)) {
        i++;
      } else if (c === "/" && src[i + 1] === "/") {
        const end = src.indexOf("\n", i);
        i = end === -1 ? n : end;
      } else if (c === "/" && src[i + 1] === "*") {
        const end = src.indexOf("*/", i + 2);
        i = end === -1 ? n : end + 2;
      } else if (c === '"' || c === "'") {
        i = readQuoted(i, c, true);
        afterValue();
      } else if (c === "`") {
        stack.push({ kind: "template" });
        i++;
      } else if (c === "/" && (prev === "" || EXPR_START.includes(prev) || REGEX_PREV_WORDS.has(prevWord))) {
        let j = i + 1;
        let inClass = false;
        while (j < n && src[j] !== "\n") {
          if (src[j] === "\\") j++;
          else if (src[j] === "[") inClass = true;
          else if (src[j] === "]") inClass = false;
          else if (src[j] === "/" && !inClass) break;
          j++;
        }
        j++;
        while (j < n && /[a-z]/i.test(src[j])) j++;
        i = j;
        afterValue();
      } else if (
        c === "<" &&
        tsx &&
        /[A-Za-z>]/.test(src[i + 1] ?? "") &&
        (prev === "" || "(,=:?[{};&|!>".includes(prev) || JSX_PREV_WORDS.has(prevWord))
      ) {
        stack.push({ kind: "tag", closing: false, started: false });
        i++;
      } else if (c === "{") {
        top.depth++;
        prev = "{";
        prevWord = "";
        i++;
      } else if (c === "}") {
        if (top.depth === 0 && stack.length > 1) {
          stack.pop();
          afterValue();
        } else {
          top.depth = Math.max(0, top.depth - 1);
          prev = "}";
          prevWord = "";
        }
        i++;
      } else if (IDENT.test(c)) {
        let j = i + 1;
        while (j < n && IDENT.test(src[j])) j++;
        prevWord = src.slice(i, j);
        prev = "a";
        i = j;
      } else {
        prev = c;
        prevWord = "";
        i++;
      }
    } else if (top.kind === "template") {
      let j = i;
      while (j < n) {
        if (src[j] === "\\") j += 2;
        else if (src[j] === "`" || (src[j] === "$" && src[j + 1] === "{")) break;
        else j++;
      }
      emit(i, Math.min(j, n));
      if (j >= n) {
        i = n;
      } else if (src[j] === "`") {
        stack.pop();
        afterValue();
        i = j + 1;
      } else {
        stack.push({ kind: "js", depth: 0 });
        prev = "{";
        prevWord = "";
        i = j + 2;
      }
    } else if (top.kind === "tag") {
      if (!top.started) {
        top.started = true;
        if (c === "/") {
          top.closing = true;
          i++;
          continue;
        }
      }
      if (c === ">") {
        stack.pop();
        if (top.closing) {
          if (stack[stack.length - 1]?.kind === "children") stack.pop();
          if (stack[stack.length - 1]?.kind === "js") afterValue();
        } else {
          stack.push({ kind: "children" });
        }
        i++;
      } else if (c === "/" && src[i + 1] === ">") {
        stack.pop();
        if (stack[stack.length - 1]?.kind === "js") afterValue();
        i += 2;
      } else if (c === '"' || c === "'") {
        i = readQuoted(i, c, false);
      } else if (c === "{") {
        stack.push({ kind: "js", depth: 0 });
        prev = "{";
        prevWord = "";
        i++;
      } else {
        i++;
      }
    } else {
      let j = i;
      while (j < n && src[j] !== "<" && src[j] !== "{") j++;
      emit(i, j);
      if (j >= n) {
        i = n;
      } else if (src[j] === "{") {
        stack.push({ kind: "js", depth: 0 });
        prev = "{";
        prevWord = "";
        i = j + 1;
      } else {
        stack.push({ kind: "tag", closing: false, started: false });
        i = j + 1;
      }
    }
  }
  return out;
}

// ---------------------------------------------------------------------------------------------------------------
// Markdown: blank out what a reader does not read as prose (code, HTML comments, link targets, URLs), keeping
// offsets so line numbers stay right.

const blank = (s) => s.replace(/[^\n]/g, " ");

export function proseOfMarkdown(src) {
  return src
    .replace(/^( {0,3})(```|~~~)[^\n]*\n[\s\S]*?(?:^\1\2[^\n]*$|(?![\s\S]))/gm, blank)
    .replace(/<!--[\s\S]*?-->/g, blank)
    .replace(/(`+)[^`\n][\s\S]*?\1/g, blank)
    .replace(/\]\([^)\s]*(?:\s+"[^"]*")?\)/g, (m) => `]${blank(m.slice(1))}`)
    .replace(/^\s{0,3}\[[^\]]+\]:\s*\S+.*$/gm, blank)
    .replace(/<https?:\/\/[^>]*>|https?:\/\/[^\s)>\]]+/g, blank);
}

// ---------------------------------------------------------------------------------------------------------------

function lineStarts(src) {
  const starts = [0];
  for (let i = 0; i < src.length; i++) if (src[i] === "\n") starts.push(i + 1);
  return starts;
}

function lineOf(starts, offset) {
  let lo = 0;
  let hi = starts.length - 1;
  while (lo < hi) {
    const mid = (lo + hi + 1) >> 1;
    if (starts[mid] <= offset) lo = mid;
    else hi = mid - 1;
  }
  return lo;
}

/**
 * @param {string} file repo-relative path
 * @param {string} src
 */
export function checkSource(file, src) {
  /** @type {{ text: string, offset: number }[]} */
  let segments;
  if (file.endsWith(".md")) {
    segments = [{ text: proseOfMarkdown(src), offset: 0 }];
  } else {
    if (GENERATED_HEADER.test(src.split("\n", 3).join("\n"))) return [];
    segments = extractTsText(src, file.endsWith(".tsx"));
  }
  const starts = lineStarts(src);
  const lines = src.split("\n");
  const ignored = (line) =>
    /writing-check-ignore(?!-next-line)/.test(lines[line] ?? "") ||
    /writing-check-ignore-next-line/.test(lines[line - 1] ?? "");

  /** @type {{ file: string, line: number, column: number, rule: string, message: string, excerpt: string }[]} */
  const found = [];
  const seen = new Set();
  for (const seg of segments) {
    for (const rule of RULES) {
      rule.re.lastIndex = 0;
      for (const m of seg.text.matchAll(rule.re)) {
        const at = seg.offset + (m.index ?? 0);
        const line = lineOf(starts, at);
        const key = `${at}:${rule.message}`;
        if (ignored(line) || seen.has(key)) continue;
        seen.add(key);
        const lineText = lines[line] ?? "";
        const col = at - starts[line];
        const from = Math.max(0, col - 40);
        found.push({
          file,
          line: line + 1,
          column: col + 1,
          rule: rule.id,
          message: rule.message,
          excerpt: `${from > 0 ? "..." : ""}${lineText.slice(from, col + 50).trim()}`,
        });
      }
    }
  }
  return found.sort((a, b) => a.line - b.line || a.column - b.column);
}

function main(argv) {
  let root = process.cwd();
  let json = false;
  for (let k = 0; k < argv.length; k++) {
    if (argv[k] === "--root") root = resolve(argv[++k] ?? ".");
    else if (argv[k] === "--json") json = true;
    else {
      process.stderr.write(`unknown argument: ${argv[k]}\nusage: check-writing.mjs [--root <dir>] [--json]\n`);
      return 2;
    }
  }
  if (!statSync(root, { throwIfNoEntry: false })?.isDirectory()) {
    process.stderr.write(`not a directory: ${root}\n`);
    return 2;
  }

  const files = selectFiles(listFiles(root));
  const violations = files.flatMap((f) => {
    let src;
    try {
      src = readFileSync(join(root, f), "utf8");
    } catch (err) {
      if (err && typeof err === "object" && "code" in err && err.code === "ENOENT") return [];
      throw err;
    }
    return checkSource(f, src);
  });

  if (json) {
    process.stdout.write(`${JSON.stringify({ files: files.length, violations }, null, 2)}\n`);
  } else {
    for (const v of violations) process.stdout.write(`${v.file}:${v.line}:${v.column}  ${v.message}  ${v.excerpt}\n`);
    process.stdout.write(
      `writing check: ${files.length} files, ${violations.length} violation${violations.length === 1 ? "" : "s"}\n`,
    );
  }
  return violations.length === 0 ? 0 : 1;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  process.exitCode = main(process.argv.slice(2));
}
